fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    let mut result = Vec::with_capacity(arr.len());
    
    if min_val <= max_val {
        // Normal case: clip values to the range [min_val, max_val]
        for &value in arr {
            if value < min_val {
                result.push(min_val);
            } else if value > max_val {
                result.push(max_val);
            } else {
                result.push(value);
            }
        }
    } else {
        // Special case: min_val > max_val, fill with max_val
        result.resize(arr.len(), max_val);
    }
    
    result
}